contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking inputs to exercise approval and a specific log call
    function run(address logger, address keepAddress, bytes32 digest, bytes32 r, bytes32 s, bytes32 txid) public payable {
        require(logger != address(0), "logger cannot be zero");
        // Initially, the logger may or may not be approved. We'll observe behavior in both cases.
        // We will call logCreated and logGotRedemptionSignature and logRedeemed as representatives.

        // First, from this contract (which is msg.sender for calls) ensure approved status for 'logger' equals false by default
        // We cannot change c._contractOwner, but the constructor deployer of c is the checker; however we can use c.setApprovedLogger only if this contract is owner. We don't know that, so we will instead observe behavior for this contract's msg.sender (InvMutTest).
        // The rule we assert uses the observable approvedToLog for this contract's address and ties it to return values of log* calls.

        bool beforeApproved = c.approvedToLog(address(this)); if (__ESBMC_reverted()) return;

        // Call three logging functions and capture whether they revert or returned true/false
        bool r1;
        bool r2;
        bool r3;
        // logCreated
        bool v1 = c.logCreated(keepAddress); bool __rev0 = __ESBMC_reverted(); if (__rev0) { r1 = false; } else { r1 = v1; }
        // logGotRedemptionSignature
        bool v2 = c.logGotRedemptionSignature(digest, r, s); bool __rev1 = __ESBMC_reverted(); if (__rev1) { r2 = false; } else { r2 = v2; }
        // logRedeemed
        bool v3 = c.logRedeemed(txid); bool __rev2 = __ESBMC_reverted(); if (__rev2) { r3 = false; } else { r3 = v3; }

        // General rule: for this contract's address, all logging functions behave consistently with approvedToLog(address(this)):
        // If approvedToLog is true then each log call must have returned true (and not reverted). If approvedToLog is false then each log call must have returned false (either by returning false or by reverting — but contract implementation returns false without revert).
        assert(
            (beforeApproved && r1 && r2 && r3) || (!beforeApproved && (!r1) && (!r2) && (!r3))
        );
    }

    receive() external payable { }
}

