pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DepositLog c;

    function setUp() public {
        c = new DepositLog();
    }

    function _run(address logger, address keepAddress, bytes32 digest, bytes32 r, bytes32 s, bytes32 txid) internal {
        vm.assume(logger != address(0));
        bool beforeApproved;
        try c.approvedToLog(address(this)) returns (bool __r) { beforeApproved = __r; } catch { return; }
        bool r1;
        bool r2;
        bool r3;
        try c.logCreated(keepAddress) returns (bool v1) { r1 = v1; } catch { r1 = false; }
        try c.logGotRedemptionSignature(digest, r, s) returns (bool v2) { r2 = v2; } catch { r2 = false; }
        try c.logRedeemed(txid) returns (bool v3) { r3 = v3; } catch { r3 = false; }
        assertTrue((beforeApproved && r1 && r2 && r3) || (!beforeApproved && (!r1) && (!r2) && (!r3)));
    }

    function testFuzz_run(address logger, address keepAddress, bytes32 digest, bytes32 r, bytes32 s, bytes32 txid) public {
        vm.assume(logger.code.length == 0 && uint160(logger) > 0xffff && logger != address(this) && logger != address(c) && logger != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logger != 0x000000000000000000636F6e736F6c652e6c6f67 && logger != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logger != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(keepAddress.code.length == 0 && uint160(keepAddress) > 0xffff && keepAddress != address(this) && keepAddress != address(c) && keepAddress != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && keepAddress != 0x000000000000000000636F6e736F6c652e6c6f67 && keepAddress != 0x4e59b44847b379578588920cA78FbF26c0B4956C && keepAddress != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(logger, keepAddress, digest, r, s, txid);
    }

    receive() external payable { }
}
